1: import React, { useMemo } from "react";
2: 
3: import { ProcessesResponse, useProcesses } from "@mtfh/common/lib/api/process/v1";
4: import {
5:   Center,
6:   ErrorSummary,
7:   SimplePagination,
8:   SimplePaginationButton,
9:   Spinner,
10:   Table,
11:   Tbody,
12: } from "@mtfh/common/lib/components";
13: import { processes as processesConfig } from "@mtfh/processes";
14: 
15: import { locale } from "../../services";
16: import { TenureProcessRecord } from "../worktray-list";
17: import { PersonProcessRecord } from "../worktray-list/person-record";
18: 
19: export interface WorktraySimpleListProps {
20:   targetId: string;
21: }
22: 
23: const NoProcesses = () => {
24:   return <p>No processes</p>;
25: };
26: 
27: const processRecordComponents = {
28:   tenure: TenureProcessRecord,
29:   person: PersonProcessRecord,
30: };
31: 
32: export const WorktraySimpleList = ({
33:   targetId,
34: }: WorktraySimpleListProps): JSX.Element => {
35:   const { data, size, setSize, error } = useProcesses(targetId);
36:   const response = useMemo<ProcessesResponse | null>(() => {
37:     if (!data) {
38:       return null;
39:     }
40:     return data[size - 1];
41:   }, [data, size]);
42: 
43:   if (error) {
44:     return (
45:       <ErrorSummary
46:         id="worktray-result-error"
47:         title={locale.errors.unableToFetchRecord}
48:         description={locale.errors.unableToFetchRecordDescription}
49:       />
50:     );
51:   }
52: 
53:   if (!response) {
54:     return (
55:       <Center>
56:         <Spinner />
57:       </Center>
58:     );
59:   }
60: 
61:   const {
62:     results: processes,
63:     paginationDetails: { nextToken },
64:   } = response;
65: 
66:   if (!processes.length) {
67:     return <NoProcesses />;
68:   }
69: 
70:   return (
71:     <div className="worktray-simple-list">
72:       <Table>
73:         <Tbody>
74:           {processes.map((process) => {
75:             const processConfig = processesConfig[process.processName];
76:             const Result = processRecordComponents[process.targetType];
77:             return (
78:               <Result
79:                 key={process.id}
80:                 process={{
81:                   ...process,
82:                   state: process.currentState.state,
83:                   processStartedAt: process.previousStates[0]?.createdAt || "",
84:                   stateStartedAt: process.currentState.createdAt,
85:                 }}
86:                 processConfig={processConfig}
87:                 simple
88:               />
89:             );
90:           })}
91:         </Tbody>
92:       </Table>
93:       {(size > 1 || nextToken) && (
94:         <SimplePagination>
95:           {size !== 1 && (
96:             <SimplePaginationButton variant="previous" onClick={() => setSize(size - 1)}>
97:               Previous
98:             </SimplePaginationButton>
99:           )}
100:           {nextToken && (
101:             <SimplePaginationButton variant="next" onClick={() => setSize(size + 1)}>
102:               Next
103:             </SimplePaginationButton>
104:           )}
105:         </SimplePagination>
106:       )}
107:     </div>
108:   );
109: };

1: import React, { useCallback, useContext, useState } from "react";
2: 
3: import { Button, Details } from "@mtfh/common/lib/components";
4: import { useAxiosSWR } from "@mtfh/common/lib/http";
5: import { Process, processes } from "@mtfh/processes";
6: 
7: import { WorktrayContext } from "../../context/worktray-context";
8: import { config } from "../../services";
9: import locale from "../../services/locale";
10: import { WorktrayFilterOptions } from "../../types";
11: import { Patch } from "../../types/patch";
12: import { FilterBox, Option } from "./filter-box";
13: 
14: import "./styles.scss";
15: 
16: const { components } = locale;
17: 
18: enum FilterType {
19:   PROCESS_NAMES = "processNames",
20:   PATCH = "patch",
21: }
22: 
23: const sortAlphaNum = ({ value: a }, { value: b }) => {
24:   const reA = /[^a-zA-Z]/g;
25:   const reN = /[^0-9]/g;
26:   const aA = a.replace(reA, "");
27:   const bA = b.replace(reA, "");
28:   if (aA === bA) {
29:     const aN = parseInt(a.replace(reN, ""), 10);
30:     const bN = parseInt(b.replace(reN, ""), 10);
31:     if (aN === bN) {
32:       return 0;
33:     }
34:     return aN > bN ? 1 : -1;
35:   }
36:   return aA > bA ? 1 : -1;
37: };
38: 
39: export const WorktrayFilters = (): JSX.Element => {
40:   const {
41:     dispatch,
42:     state: { patch, areaId, processNames, status },
43:   } = useContext(WorktrayContext);
44: 
45:   const { data: patches } = useAxiosSWR<Patch[]>(
46:     `${config.patchesAndAreasApiUrl}/patch?parentId=${areaId}`,
47:   );
48: 
49:   const filters: { type: string; title: string; options: Option[]; isRadio?: boolean }[] =
50:     [
51:       {
52:         type: FilterType.PROCESS_NAMES,
53:         title: "Processes",
54:         options: (Object.values(Process) as string[]).map((processName) => {
55:           const key = processes[processName].processName;
56:           const value = processes[processName].name;
57:           return {
58:             key,
59:             value,
60:           };
61:         }),
62:         isRadio: false,
63:       },
64:     ];
65: 
66:   if (patches) {
67:     filters.push({
68:       type: FilterType.PATCH,
69:       title: "Patches",
70:       options: patches
71:         ?.map((item) => ({ key: item.id, value: item.name }))
72:         .sort(sortAlphaNum),
73:       isRadio: true,
74:     });
75:   }
76: 
77:   const [selectedFilters, setSelectedFilters] = useState<
78:     Record<WorktrayFilterOptions, string[]>
79:   >({
80:     patch: patch?.split(",") || [],
81:     processNames: processNames?.split(",") || [],
82:     status: status?.split(",") || [],
83:   });
84: 
85:   const handleCheckboxFilters = (
86:     event: React.ChangeEvent<HTMLInputElement>,
87:     filterType: string,
88:   ) => {
89:     let updatedFilters: string[] = [...selectedFilters[filterType]];
90:     if (event.target.checked) {
91:       const { options, isRadio } =
92:         filters.find((filter) => filter.type === filterType) || {};
93:       if (event.target.value === "show-all") {
94:         updatedFilters = options?.map((option) => option.key) || [];
95:       } else if (isRadio) {
96:         updatedFilters = [event.target.value];
97:       } else {
98:         updatedFilters.push(event.target.name);
99:       }
100:     } else {
101:       updatedFilters.splice(selectedFilters[filterType].indexOf(event.target.name), 1);
102:     }
103:     setSelectedFilters({
104:       ...selectedFilters,
105:       [filterType]: updatedFilters,
106:     });
107:   };
108: 
109:   const handleSelectAll = (filterType: string) => {
110:     setSelectedFilters({
111:       ...selectedFilters,
112:       [filterType]:
113:         filters
114:           .find((filter) => filter.type === filterType)
115:           ?.options.map((option) => option.key) || [],
116:     });
117:   };
118: 
119:   const handleRemoveAll = (filterType: string) => {
120:     setSelectedFilters({
121:       ...selectedFilters,
122:       [filterType]: [],
123:     });
124:   };
125: 
126:   const applyFilters = useCallback(
127:     (data) => {
128:       (Object.keys(data) as WorktrayFilterOptions[]).forEach((filterType) => {
129:         dispatch({
130:           type: "FILTER",
131:           payload: {
132:             type: filterType,
133:             payload: String(data[filterType]),
134:           },
135:         });
136:       });
137:     },
138:     [dispatch],
139:   );
140: 
141:   const clearFilters = () => {
142:     Object.keys(selectedFilters).forEach((filterType) => {
143:       if (filterType === FilterType.PATCH) {
144:         selectedFilters[filterType] =
145:           filters
146:             .find((filter) => filter.type === FilterType.PATCH)
147:             ?.options.map((option) => option.key) || [];
148:       } else {
149:         selectedFilters[filterType] = [];
150:       }
151:     });
152:     applyFilters(selectedFilters);
153:   };
154: 
155:   return (
156:     <Details className="worktray-filters" title="Filter by" open>
157:       <>
158:         <div className="worktray-filters__boxes">
159:           {filters.map(({ title, options, type, isRadio }) => {
160:             return (
161:               <FilterBox
162:                 key={title}
163:                 filterType={type}
164:                 title={title}
165:                 options={options}
166:                 handleSelectAll={handleSelectAll}
167:                 handleRemoveAll={handleRemoveAll}
168:                 handleCheckboxFilters={handleCheckboxFilters}
169:                 selectedFilters={selectedFilters}
170:                 isRadio={isRadio}
171:               />
172:             );
173:           })}
174:         </div>
175: 
176:         <div className="worktray-filters__actions">
177:           <Button
178:             className="worktray-filters__apply-button"
179:             onClick={() => applyFilters(selectedFilters)}
180:           >
181:             {components.filters.applyFilters}
182:           </Button>
183:           <button
184:             className="worktray-filters__clear-filters select-all lbh-link lbh-link--no-visited-state"
185:             onClick={() => clearFilters()}
186:           >
187:             {components.filters.clearFilters}
188:           </button>
189:         </div>
190:       </>
191:     </Details>
192:   );
193: };

