30:   [processes.soletojoint.processName]: SoleToJointSideBar,
31:   [processes.changeofname.processName]: ChangeOfNameSideBar,
32: };
33: 
34: const isSameState = (firstState, secondState) => {
35:   return firstState.state === secondState.state;
36: };
37: 
38: export const ProcessLayout = (): JSX.Element => {
39:   const { processId, processName } =
40:     useParams<{ processId: string; processName: string }>();
41: 
42:   const [isCloseProcessDialogOpen, setCloseProcessDialogOpen] = useState<boolean>(false); // used by Close Case button
43:   const [isCancel, setCancel] = useState<boolean>(false); // used by Cancel Process button
44:   const [submitted, setSubmitted] = useState<boolean>(false); // used at Finish pages
45:   const processConfig = processName && processes[processName];
46:   const { states } = processConfig || {};
47:   const { processClosed } = states || {};
48: 
49:   const {
50:     data: process,
51:     error,
52:     mutate,
53:   } = useProcess({
54:     id: processId,
55:     processName,
56:   });
57: 
58:   const [closeProcessReason, setCloseProcessReason] = useState<string>();
59: 
60:   useEffect(() => {
61:     if (!closeProcessReason) {
62:       setCloseProcessReason(
63:         process && processClosed && isSameState(process.currentState, processClosed)
64:           ? process?.currentState.processData.formData?.reason
65:           : process?.currentState.processData.formData?.comment,
66:       );
67:     }
68:   }, [process, closeProcessReason, processClosed]);
69: 
70:   if (error) {
71:     return (
72:       <ErrorSummary
73:         id="sole-to-joint-view"
74:         title={locale.errors.unableToFetchRecord}
75:         description={locale.errors.unableToFetchRecordDescription}
76:       />
77:     );
78:   }
79: 
80:   if (!process) {
81:     return (
82:       <Center>
83:         <Spinner />
84:       </Center>
85:     );
86:   }
87: 
88:   const Component = components[processName];
89:   const Sidebar = sidebars[processName];
90: 
91:   if (!Component) {
92:     return (
93:       <ErrorSummary
94:         id="process-layout-error"
95:         title={locale.errors.unableToFindState}
96:         description={locale.errors.unableToFindStateDescription}
97:       />
98:     );
99:   }
100: 
101:   return (
102:     <Layout
103:       data-testid="process-layout"
104:       sidePosition="right"
105:       backLink={
106:         <Link
107:           as={RouterLink}
108:           to={`/processes/${processName}/start/${process.targetType}/${process.targetId}`}
109:           variant="back-link"
110:         >
111:           {locale.backButton}
112:         </Link>
113:       }
114:       side={
115:         <Sidebar
116:           process={process}
117:           submitted={submitted}
118:           closeProcessReason={closeProcessReason}
119:           setCloseProcessDialogOpen={setCloseProcessDialogOpen}
120:           setCancel={setCancel}
121:         />
122:       }
123:     >
124:       <Heading variant="h1">{processConfig.title}</Heading>
125:       <Component
126:         process={process}
127:         mutate={mutate}
128:         optional={{
129:           submitted,
130:           setSubmitted,
131:           isCancel,
132:           setCancel,
133:           setCloseProcessDialogOpen,
134:           closeProcessReason,
135:         }}
136:       />
137: 
138:       <CloseProcessDialog
139:         isCloseProcessDialogOpen={isCloseProcessDialogOpen}
140:         setCloseProcessDialogOpen={setCloseProcessDialogOpen}
141:         setCloseProcessReason={setCloseProcessReason}
142:         mutate={mutate}
143:         isCancel={isCancel}
144:       />
145: 
146:       <hr className="divider" />
147:       <CommentsView targetType="process" targetId={processId} mutate={mutate} />
148:     </Layout>
149:   );
150: };

