202:         results: data?.results.processes,
203:         total: data?.total,
204:         error,
205:       },
206:       dispatch,
207:     }),
208:     [state, data, error, dispatch],
209:   );
210: 
211:   return <WorktrayContext.Provider value={value}>{children}</WorktrayContext.Provider>;
212: };
213: 
214: export const PersistWorktrayContextURL = ({
215:   sessionKey,
216: }: {
217:   sessionKey?: string;
218: }): null => {
219:   const {
220:     state: { page, pageSize, order, sort, timePeriod, patch, processNames, status },
221:   } = useContext(WorktrayContext);
222:   const { push } = useHistory();
223: 
224:   useEffect(() => {
225:     const query = new URLSearchParams();
226:     if (page > 1) {
227:       query.set("p", String(page));
228:     }
229: 
230:     if (pageSize !== LimitOptions.SMALL) {
231:       query.set("l", String(pageSize));
232:     }
233: 
234:     query.set("t", String(timePeriod));
235: 
236:     if (order && order !== OrderByOptions.ASC) {
237:       query.set("o", order);
238:     }
239: 
240:     query.set("sort", String(sort));
241: 
242:     if (patch) {
243:       query.set("patch", patch);
244:     }
245: 
246:     if (processNames) {
247:       query.set("processNames", processNames);
248:     }
249: 
250:     if (status) {
251:       query.set("status", status);
252:     }
253: 
254:     const path = `?${query.toString()}`;
255:     push(path);
256: 
257:     if (sessionKey) {
258:       window.sessionStorage.setItem(sessionKey, path);
259:     }
260:   }, [
261:     page,
262:     pageSize,
263:     order,
264:     sort,
265:     sessionKey,
266:     push,
267:     timePeriod,
268:     patch,
269:     processNames,
270:     status,
271:   ]);
272: 
273:   return null;
274: };
275: 
276: export const WorktrayURLProvider: FC<{
277:   sessionKey?: string;
278:   patchId?: string | null;
279:   areaId?: string | null;
280: }> = ({ children, sessionKey, patchId, areaId }): JSX.Element => {
281:   const { search } = useLocation();
282:   const query = new URLSearchParams(search);
283:   const page = Number(query.get("p") || 1);
284:   const pageSize = Number(query.get("l") || 10);
285:   const timePeriod = (query.get("t") || "") as TimePeriodOptions;
286:   const patch = query.get("patch") || patchId || "";
287:   const processNames = query.get("processNames") || "";
288:   const status = query.get("status") || "";
289:   const sortBy = query.get("sort");
290:   const orderBy = query.get("o");
291: 
292:   const sort = useMemo(() => {
293:     if (sortBy === "name") {
294:       return ProcessSortOptions.NAME;
295:     }
296:     return ProcessSortOptions.STATUS;
297:   }, [sortBy]);
298: 
299:   const order = useMemo(() => {
300:     if (orderBy === "desc") {
301:       return OrderByOptions.DESC;
302:     }
303:     return OrderByOptions.ASC;
304:   }, [orderBy]);
305: 
306:   return (
307:     <WorktrayProvider
308:       initial={{
309:         page,
310:         sort,
311:         order,
312:         pageSize,
313:         timePeriod,
314:         patch,
315:         areaId,
316:         processNames,
317:         status,
318:       }}
319:     >
320:       {children}
321:       <PersistWorktrayContextURL sessionKey={sessionKey} />
322:     </WorktrayProvider>
323:   );
324: };

