1: import React from "react";
2: import { Link as RouterLink } from "react-router-dom";
3: 
4: import { addDays, differenceInDays, differenceInHours, parseISO } from "date-fns";
5: 
6: import { Link, Td, Text, Tr } from "@mtfh/common/lib/components";
7: import { formatDate } from "@mtfh/common/lib/utils";
8: import { IProcess, ProcessStateInfo } from "@mtfh/processes";
9: 
10: import { Process, ProcessName } from "../../types";
11: 
12: import "./styles.scss";
13: 
14: export interface ProcessRecordProps {
15:   person: {
16:     id?: string;
17:     fullName?: string;
18:   };
19:   property?: {
20:     id?: string;
21:     address?: string;
22:   };
23:   process: Process;
24:   processConfig: IProcess | undefined;
25:   simple?: boolean;
26: }
27: 
28: enum ProcessStates {
29:   PROCESS_CLOSED = "ProcessClosed",
30:   PROCESS_CANCELLED = "ProcessCancelled",
31:   PROCESS_COMPLETED = "ProcessCompleted",
32: }
33: 
34: export const ProcessRecord = ({
35:   person,
36:   property,
37:   process,
38:   processConfig,
39:   simple = false,
40: }: ProcessRecordProps): JSX.Element => {
41:   const processName = processConfig?.name || process.processName;
42:   const timeConstraint =
43:     processConfig?.states[process.state.charAt(0).toLowerCase() + process.state.slice(1)]
44:       ?.timeConstraint;
45:   let status;
46:   if (processConfig) {
47:     const statesInfo: ProcessStateInfo[] = Object.values(processConfig?.states);
48:     status = statesInfo.find((item) => item.state === process.state)?.status;
49:   }
50: 
51:   let daysDiff = 0;
52:   let hoursLeft = 48;
53:   if (timeConstraint) {
54:     daysDiff =
55:       timeConstraint - differenceInDays(new Date(), parseISO(process.stateStartedAt));
56:     const completionDate = addDays(parseISO(process.stateStartedAt), timeConstraint);
57:     hoursLeft = differenceInHours(completionDate, new Date());
58:   }
59: 
60:   const isClosed =
61:     status &&
62:     [
63:       ProcessStates.PROCESS_CLOSED,
64:       ProcessStates.PROCESS_CANCELLED,
65:       ProcessStates.PROCESS_COMPLETED,
66:     ].includes(status);
67: 
68:   const getState = () => {
69:     if (process.state === ProcessStates.PROCESS_CANCELLED) {
70:       return { title: "Cancelled", date: formatDate(process.stateStartedAt) };
71:     }
72:     if (process.state === ProcessStates.PROCESS_CLOSED) {
73:       return { title: "Closed", date: formatDate(process.stateStartedAt) };
74:     }
75:     if (process.state === ProcessStates.PROCESS_COMPLETED) {
76:       return { title: "Completed", date: formatDate(process.stateStartedAt) };
77:     }
78:     return {
79:       title: "Initiated",
80:       date: formatDate(process.processStartedAt),
81:     };
82:   };
83: 
84:   const state = getState();
85: 
86:   const getStatusColor = () => {
87:     if (
88:       status &&
89:       (
90:         [ProcessStates.PROCESS_CLOSED, ProcessStates.PROCESS_CANCELLED] as string[]
91:       ).includes(process.state)
92:     ) {
93:       return "orange";
94:     }
95:     if (status && process.state === ProcessStates.PROCESS_COMPLETED) {
96:       return "green";
97:     }
98:     if (daysDiff === timeConstraint) {
99:       return "grey";
100:     }
101:     if (hoursLeft >= 48) {
102:       return "aqua";
103:     }
104:     if (hoursLeft > 0 && hoursLeft < 48) {
105:       return "amber";
106:     }
107:     return "red";
108:   };
109: 
110:   return (
111:     <Tr className="govuk-table__row process-record">
112:       <Td className="process-record__item">
113:         <Link
114:           as={RouterLink}
115:           to={`/person/${person.id}`}
116:           variant="link"
117:           target="_blank"
118:           className="lbh-heading-h4"
119:           data-testid="person-link"
120:         >
121:           {person.fullName}
122:         </Link>
123:         {property && property.id && property.address && (
124:           <Link
125:             className="--address"
126:             as={RouterLink}
127:             to={`/property/${property.id}`}
128:             variant="link"
129:             target="_blank"
130:             data-testid="property-link"
131:           >
132:             {property.address}
133:           </Link>
134:         )}
135:       </Td>
136:       <Td className="process-record__item --processName">
137:         <Link
138:           as={RouterLink}
139:           to={`/processes/${
140:             Number.isInteger(process.processName)
141:               ? ProcessName[process.processName]
142:               : process.processName
143:           }/${process.id}`}
144:           variant="link"
145:           target="_blank"
146:           className="lbh-heading-h4"
147:         >
148:           {processName}
149:         </Link>
150:       </Td>
151:       {!simple && (
152:         <Td className="process-record__item">
153:           <Text>{process.patchAssignment?.patchName}</Text>
154:         </Td>
155:       )}
156:       <Td className="process-record__item">
157:         <Text className="title">{state.title}</Text>
158:         <Text className="createdAt">{state.date}</Text>
159:       </Td>
160:       {!simple && (
161:         <Td className="process-record__item">
162:           <Text>
163:             {isClosed || !timeConstraint
164:               ? "-"
165:               : `${Math.abs(daysDiff)} days ${daysDiff > 0 ? "left" : "overdue"}`}
166:           </Text>
167:         </Td>
168:       )}
169:       <Td className="process-record__item --status">
170:         <span className={`govuk-tag lbh-tag box ${getStatusColor()}`}>
171:           {status || ""}
172:         </span>
173:         {!simple && (
174:           <Text size="sm">
175:             {!isClosed &&
176:               timeConstraint &&
177:               `${Math.abs(daysDiff)} days ${daysDiff > 0 ? "left" : "overdue"}`}
178:           </Text>
179:         )}
180:       </Td>
181:     </Tr>
182:   );
183: };

